import { requireUser, requireRole } from '@/lib/auth';
import { json, readJson, route } from '@/lib/http';
import { audit } from '@/lib/audit';
import { searchByName } from '@/repos/patients';

const Body = z.object({ q: z.string().trim().min(2).max(100) });

/** Name search in the practitioner's own practice. POST so the search term never appears in a URL. */
export const POST = route(async (req) => {
  const user = await requireUser(req);
  requireRole(user, 'practitioner');
  const { q } = Body.parse(await readJson(req));
  const rows = await searchByName(user.orgId, q, 20);
  await audit(user, 'patients.search', 'org', user.orgId);
  return json({
    results: rows.map((r) => ({
      id: r.id,
      firstName: r.first_name,
      lastName: r.last_name,
      dateOfBirth: r.date_of_birth,
    })),
  });
});

